  function updateNPCShadows(){for(const item of npcShadows){const p=item.rig.group.position,root=item.rig.group.parent.position,distance=Math.hypot(root.x+p.x-camera.position.x,root.z+p.z-camera.position.z),near=distance<(item.near?24:20);if(near!==item.near){item.near=near;for(const o of item.casters)o.castShadow=near;}item.contact.visible=!near&&item.rig.group.visible;}}
